const testCUtmCampaignByButtonClick: Record<string, string> = {
  createWithAi: 'testCAi',
  useVisualEditor: 'testCVisual'
};

const resolveUtmCampaign = (variant: EditorChooserVariant, buttonClick: string): string => {
