    window.open(
      getMermaidAiLiveUrl({
        utmCampaign: resolveUtmCampaign(variant, buttonClick),
        utmMedium
      }),
      '_blank',
      'noopener'
    );
  };

  return { log, startTrial, dismiss, openMermaidAiLive };
};
