      parsed = JSON.parse(config) as MermaidConfig;
    } catch {
      parsed = {};
    }
  } else if (config) {
    parsed = config;
  }
  stripConfigPaths(parsed, findUnsafeConfigPaths(parsed));
  return parsed;
};
