const isOnlyDefaultTheme = (config: string): boolean => {
  try {
    const parsed: unknown = JSON.parse(config);
    return (
      typeof parsed === 'object' &&
      parsed !== null &&
      Object.keys(parsed).length === 1 &&
      (parsed as MermaidConfig).theme === 'default'
    );
  } catch {
    return false;
  }
};

